 def flush(self,cams=[]):
  if not self.buf:return
  a=np.asarray(self.buf);self.buf=[]
  for start in range(0,len(a),180):
   part=a[start:start+180];before=self.r.status()
   try: res=self.r.submit('ee_pose',part,dt=.05,video='none',cameras=cams)
   except Exception:
    status=self.r.wait_ready();
    if status['control_steps']==before['control_steps']:res=self.r.submit('ee_pose',part,dt=.05,video='none',cameras=cams)
    else: raise RuntimeError('Ambiguous completed call; inspect before continuing')
   if any(p['ik_failures'] for p in res.meta.get('plan',[])): print('IK failures',res.meta['plan'],flush=True)
   if res.stopped:raise RuntimeError('Partial execution')
   with open(ROOT+'/execution.jsonl','a') as f:f.write(json.dumps({'targets':part.tolist(),'steps':res.meta['control_steps'],'calls':res.meta['calls']})+'\n')
  return res
 def move(self,xyz,speed=.12,hold=0):
  xyz=np.array(xyz);n=max(1,int(np.ceil(np.linalg.norm(xyz-self.pose[:3])/speed/.05)))
  for p in np.linspace(self.pose[:3],xyz,n+1)[1:]:self.buf.append([*p,*self.q])
  self.buf += [[*xyz,*self.q]]*round(hold/.05);self.pose=np.array([*xyz,*self.q])
 def dip(self,k):
  j=k%6;row=k//6
