  y=.14+.022*row
  self.move([self.pose[0],self.pose[1],.055]);self.move([x,y,.055]);self.move([x,y,.024],.07,.3);self.move([x,y,.055],.07)
 def park(self):
  self.move([self.pose[0],self.pose[1],.065]);self.move([-.30,0,.14]);self.flush()
 def obs(self,name,cams=['canvas_cam','practice_cam']):
  o=self.r.get_obs(cameras=cams);o.save(ROOT+'/'+name)
