   color=max(set(strokes[i]['c'] for i in ready),key=lambda c:sum(strokes[i]['c']==c for i in ready));same=[i for i in ready if strokes[i]['c']==color];switch+=1
  i=min(same,key=lambda j:np.linalg.norm(pos-[strokes[j]['x'],strokes[j]['y']]))
